package ru.mcsa.bukkit;
import java.util.*;import org.bukkit.*;import org.bukkit.entity.*;import org.bukkit.inventory.*;import org.bukkit.event.entity.*;
public final class DeathEvents {
 public static void run(String[] a){int index=a[0].equals("1")?10:1;Player player=index==10?Host.player(a,1):null;String uuid=a[index++];boolean keep=a[index++].equals("1");List<ItemStack> drops=new ArrayList<>();for(int i=index;i<a.length;i+=3)drops.add(ItemStack.fromHost(Material.matchMaterial(a[i]),Integer.parseInt(a[i+1]),a[i+2]));EntityDeathEvent event=player==null?new EntityDeathEvent((LivingEntity)RemoteEntity.find(uuid),drops):new PlayerDeathEvent(player,keep,drops);RuntimeState.fire(event);StringBuilder result=new StringBuilder();if(event.getDrops().size()>512)throw new IllegalArgumentException("Слишком много предметов смерти (512)");for(ItemStack item:event.getDrops()){if(item==null||item.isEmpty())continue;String metadata=item.metadata();if(metadata.indexOf('\n')>=0)throw new IllegalArgumentException("Перевод строки в метаданных предмета");result.append(Ascii.lower(item.getType().name())).append('\n').append(item.getAmount()).append('\n').append(metadata).append('\n');}Host.call(22,result.toString());}
}
